#include "dlaa/library.hpp"
#include "dlaa/search.hpp"
#include "dlaa/recommendation.hpp"
#include "dlaa/persistence.hpp"
#include "dlaa/benchmark.hpp"
#include "dlaa/algorithms.hpp"
#include <iostream>
#include <limits>
using namespace dlaa;
static int askInt(const char*p){int n;std::cout<<p;if(!(std::cin>>n)){std::cin.clear();std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');return -1;}std::cin.ignore(std::numeric_limits<std::streamsize>::max(),'\n');return n;}
int main(int argc,char**argv){Library lib;std::string err,dir=argc>1?argv[1]:"data/small";if(!loadBooksCsv(dir+"/books.csv",lib,err)||!loadUsersCsv(dir+"/users.csv",lib,err)){std::cerr<<err<<'\n';return 1;}SearchEngine search(lib);Recommender rec(lib);for(;;){std::cout<<"\nDIGITAL LIBRARY DAA\n1 Browse\n2 Search\n3 Recommend\n4 Algorithm workbench\n5 Benchmark sorting\n0 Exit\n";int c=askInt("Choice: ");if(c==0)break;if(c==1){for(auto&b:lib.books())std::cout<<b.id<<" | "<<b.title<<" — "<<b.author<<'\n';}else if(c==2){int m=askInt("1 ID 2 title 3 author 4 category 5 keyword 6 text: ");std::string q;std::cout<<"Query: ";std::getline(std::cin,q);std::vector<const Book*>v;if(m==1)v=search.byId(std::stoi(q));else if(m==2)v=search.byTitle(q);else if(m==3)v=search.byAuthor(q);else if(m==4)v=search.byCategory(q);else if(m==5)v=search.byKeyword(q);else if(m==6){std::string a;std::cout<<"Matcher (naive/kmp/rabin-karp/automaton): ";std::getline(std::cin,a);v=search.byPattern(q,a);}for(auto*b:v)std::cout<<b->id<<" | "<<b->title<<'\n';std::cout<<v.size()<<" result(s)\n";}else if(c==3){int id=askInt("User ID: ");for(auto&r:rec.recommend(id)){auto*b=lib.findBook(r.book_id);if(b)std::cout<<b->title<<" score="<<r.score<<" ("<<r.reason<<")\n";}}else if(c==4){int m=askInt("1 sort 2 matchers 3 knapsack 4 Dijkstra 5 CRT: ");if(m==1){std::vector<int>a{8,1,5,2};algo::mergeSort(a);for(int x:a)std::cout<<x<<' ';std::cout<<'\n';}else if(m==2){std::string t,p;std::cout<<"Text: ";std::getline(std::cin,t);std::cout<<"Pattern: ";std::getline(std::cin,p);std::cout<<algo::naiveMatch(t,p)<<' '<<algo::rabinKarp(t,p)<<' '<<algo::kmp(t,p)<<' '<<algo::finiteAutomatonMatch(t,p)<<'\n';}else if(m==3)std::cout<<algo::knapsack01({2,3,4},{3,4,5},5)<<'\n';else if(m==4){auto d=algo::dijkstra(3,{{0,1,2},{1,2,3},{0,2,9}},0);for(int x:d)std::cout<<x<<' ';std::cout<<'\n';}else if(m==5)std::cout<<algo::chineseRemainder({2,3,2},{3,5,7})<<'\n';}else if(c==5){if(runSortingBenchmark("results/sorting.csv",err))std::cout<<"Wrote results/sorting.csv\n";else std::cout<<err<<'\n';}else std::cout<<"Invalid option\n";}return 0;}
